  "meal (okuma, tam okuma sonu): 3:154 'Sonra' ('sümme'); 'kederin ardından' ('min ba'di'l-ğamm', 'min' karşılıksız, 'ba'di' 'ardından' ile); 'üzerinize … indirdi' ('enzele 'aleykum', ''alâ' 'üzeri-' ile); 'bir güven … bir uyuklama' ('emeneten nu'âsâ', 'bir' takdirleri, bedel ':' ile); 'sizden bir topluluğu saran' ('yağşâ tâ'ifeten minkum', 'min' '-den' ile, 'bir' takdir); 'Bir topluluğu ise' ('ve tâ'ifetun', 've' 'ise' ile (CIRC), 'bir' takdir); 'kendi canları kaygılandırmıştı' ('qad ehemmethum enfusuhum', 'qad' karşılıksız ('-mıştı' kipiyle örtük), 'kendi' takdir); 'Allah hakkında' ('bi'llâh', 'bi' 'hakkında' ile); 'hakka aykırı olarak' ('ğayra'l-haqq', 'olarak' takdir); 'câhiliye zannıyla zanda bulunuyor' ('yezunnûne … zanne'l-câhiliyye', '-la' takdir); 'Bu işten bize bir şey var mı?' ('hel lenâ mine'l-emri min şey'', 'hel' '-mı' ile, 'li' '-e' ile, 'mine'l-emr'deki 'min' '-den' ile, 'min şey''deki 'min' karşılıksız, 'Bu', 'bir', 'var' takdir); 'diyorlardı' ('yeqûlûne'); 'De ki' ('qul'); 'İşin tamamı Allah'ındır' ('inne'l-emra kullehû li'llâh', 'inne' karşılıksız, 'kull' 'tamamı' ile, 'li' '-ın' ile, '-dır' takdir); 'Sana açığa vurmadıklarını içlerinde gizliyorlar' ('yuxfûne fî enfusihim mâ lâ yubdûne lek', 'fî' '-de' ile, 'mâ' '-dıklarını' ile, 'lâ' '-ma' ile, 'li' '-a' ile); 'Bu işten bize bir şey olsaydı burada öldürülmezdik' ('lev kâne lenâ mine'l-emri şey'un mâ qutilnâ hâhunâ', 'lev' '-saydı' ile, 'li' '-e' ile, 'min' '-den' ile, 'mâ' '-mez' ile, 'Bu' ve 'bir' takdir); 'diyorlar' ('yeqûlûne'); 'Evlerinizde olsaydınız bile' ('lev kuntum fî buyûtikum', 'lev' '-saydınız' ile, 'fî' '-de' ile, 'bile' takdir); 'üzerlerine öldürülmek yazılmış olanlar' ('ellezîne kutibe 'aleyhimu'l-qatl', ''alâ' 'üzeri-' ile, 'öldürülmek' masdar 'qatl'ın edilgen karşılığı (takdir)); 'yatacakları yerlere çıkarlardı' ('le-beraza … ilâ medâci'ihim', 'le' karşılıksız ('-lardı' kipiyle örtük), 'ilâ' '-e' ile, 'yatacakları' takdir); 'Bu, Allah'ın göğüslerinizdekini sınaması … içindir' ('ve li-yebteliya'llâhu mâ fî sudûrikum', 've' karşılıksız, 'li' 'için' ile, 'Bu' ve '-dir' takdir, 'mâ fî' '-deki' ile); 've kalplerinizdekini arındırması' ('ve li-yumahhisa mâ fî qulûbikum', 've' 've' ile, 'li' karşılıksız (önceki 'için'e dayanır), 'mâ fî' '-deki' ile); 'Allah göğüslerin özünü bilendir' ('ve'llâhu 'alîmun bi-zâti's-sudûr', 've' karşılıksız, 'bi' '-ü' ile, 'zât' 'öz' ile, '-dir' takdir); 3:155 'İki topluluğun karşılaştığı gün' ('yevme'l-teqa'l-cem'ân', ikil 'İki' ile); 'içinizden geri dönenleri' ('inne'llezîne tevellev minkum', 'inne' karşılıksız, 'min' '-den' ile); 'ancak … şeytan kaydırdı' ('innemâ istezellehumu'ş-şeytân', 'innemâ' 'ancak' ile); 'kazandıklarının bir kısmı yüzünden' ('bi-ba'di mâ kesebû', 'bi' 'yüzünden' ile, 'mâ' '-dıkları' ile); 'Andolsun, Allah onları affetti' ('ve le-qad 'afa'llâhu 'anhum', 've' karşılıksız, 'le' ve 'qad' 'Andolsun' ile, ''an' '-ı' ile); 'Şüphesiz Allah bağışlayandır, halîmdir' ('inna'llâhe ğafûrun halîm', 'inne' 'Şüphesiz' ile, '-dır' ve '-dir' takdir)",
